// A trusted deputy, granted env:read:SECRET. It reads an env var on a caller's
// behalf -- the classic confused-deputy shape. Under nearest-frame attribution
// (precedence row 1) the deputy's frame is the only user frame the check sees,
// so an ungranted caller launders the deputy's authority. Stack-intersection
// (row 3, opt-in via deputyClasses) additionally constrains the op by whoever
// called the deputy, closing the laundering.
export function readEnv(name) {
  return Deno.env.get(name);
}
